@extends('layouts.app') @section('header','Bus Operator Management') @section('content')<h1 class="page-title">Bus Operators</h1><p class="muted">Approve, activate, deactivate and monitor registered companies.</p><div class="card"><table><tr><th>Company</th><th>Owner</th><th>Contact</th><th>Buses</th><th>Trips</th><th>Status</th><th>Action</th></tr>@foreach($operators as $o)<tr><td><b>{{$o->company_name}}</b><br><span class="muted">{{$o->permit_or_registration_no}}</span></td><td>{{$o->owner_name}}</td><td>{{$o->email}}<br>{{$o->phone}}</td><td>{{$o->buses_count}}</td><td>{{$o->trips_count}}</td><td><span class="badge {{$o->status==='active'?'success':($o->status==='pending'?'warning':'danger')}}">{{$o->status}}</span></td><td><form method="POST" action="{{route('admin.operators.toggle',$o)}}">@csrf @method('PATCH')<button class="btn btn-sm">{{$o->status==='active'?'Deactivate':'Activate'}}</button></form></td></tr>@endforeach</table>{{$operators->links()}}</div>@endsection